import { motion } from 'framer-motion';
import { TrendingUp, TrendingDown } from 'lucide-react';
import { getStockName, getStockIndustry, extractStockCode } from '../../lib/stockMap';

function pickFlowValue(item) {
  const value = Number(item?.value ?? item?.net_amount_yi ?? item?.net_amount ?? 0);
  return Number.isFinite(value) ? value : 0;
}

function pickFlowChange(item) {
  const raw = item?.change ?? item?.change_pct ?? item?.pct_chg;
  if (raw === null || raw === undefined || raw === '') return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

function pickFlowName(item) {
  const rawName = item?.name || item?.board_name || item?.ts_code || item?.symbol || '';
  // 如果是纯代码格式 (如 600105.SH)，尝试解析为中文名
  if (/^\d{6}\.(SH|SZ)$/.test(rawName)) {
    return getStockName(rawName);
  }
  return rawName || '数据暂缺';
}

function FlowTable({ title, items = [], direction = 'in' }) {
  const safeItems = Array.isArray(items) ? items : [];
  const max = Math.max(...safeItems.map((item) => Math.abs(pickFlowValue(item))), 1);

  return (
    <div className="rounded-[22px] border border-[var(--border-color)] bg-[var(--bg-surface)] p-4">
      <div className="mb-3 flex items-center gap-2 text-[var(--text-primary)]">
        {direction === 'in' ? <TrendingUp className="h-4 w-4 text-emerald-600" /> : <TrendingDown className="h-4 w-4 text-rose-600" />}
        <div className="text-base font-semibold">{title}</div>
      </div>

      <div className="space-y-2">
        <div className="grid grid-cols-[34px_1fr_60px_84px] gap-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2 text-[11px] uppercase tracking-[0.16em] text-[var(--text-secondary)]">
          <span>Rank</span>
          <span>Name</span>
          <span>Industry</span>
          <span>Net</span>
        </div>

        {safeItems.length ? (
          safeItems.map((item, index) => {
            const value = pickFlowValue(item);
            const change = pickFlowChange(item);
            const displayName = pickFlowName(item);
            const industry = getStockIndustry(item?.name || '');
            const width = `${(Math.abs(value) / max) * 100}%`;
            const positive = value >= 0;
            const hasChange = change !== null;
            return (
              <div key={`${displayName}-${index}`} className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2">
                <div className="grid grid-cols-[34px_1fr_60px_84px] gap-2 items-center">
                  <span className="text-sm font-semibold text-amber-600">{index + 1}</span>
                  <div className="min-w-0">
                    <div className="truncate text-sm text-[var(--text-primary)] font-medium">{displayName}</div>
                    <div className="truncate text-[10px] text-[var(--text-secondary)]">{item?.name || ''}</div>
                  </div>
                  <span className="truncate text-xs text-[var(--text-secondary)]">{industry}</span>
                  <span className={`text-sm font-semibold ${positive ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {positive && direction === 'in' ? '+' : ''}
                    {value.toFixed(2)} 亿
                  </span>
                </div>
                <div className="mt-2 h-2 rounded-full bg-[var(--bg-surface)]">
                  <div
                    className={`h-2 rounded-full ${
                      direction === 'in'
                        ? 'bg-gradient-to-r from-emerald-400 to-cyan-400'
                        : 'bg-gradient-to-r from-rose-500 to-orange-400'
                    }`}
                    style={{ width }}
                  />
                </div>
              </div>
            );
          })
        ) : (
          <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-4 text-sm text-[var(--text-secondary)]">
            暂无资金流数据
          </div>
        )}
      </div>
    </div>
  );
}

const THEME_STYLE = {
  main: {
    badge: 'border-rose-400/20 bg-rose-50 text-rose-700',
    bar: 'from-rose-500 to-orange-400',
    title: '主线板块',
    hint: '主升轮动',
  },
  watch: {
    badge: 'border-amber-300/20 bg-amber-50 text-amber-700',
    bar: 'from-amber-400 to-yellow-300',
    title: '观察板块',
    hint: '轮动补涨',
  },
  alive: {
    badge: 'border-emerald-300/20 bg-emerald-50 text-emerald-700',
    bar: 'from-emerald-400 to-cyan-400',
    title: '活口板块',
    hint: '尾盘观察',
  },
};

function ThemeFlowCard({ title, items = [], tone = 'main' }) {
  const style = THEME_STYLE[tone] || THEME_STYLE.main;
  const safeItems = Array.isArray(items) ? items : [];
  const max = Math.max(...safeItems.map((item) => Math.abs(Number(item.score ?? item.strength ?? item.change ?? 0))), 1);

  return (
    <div className="rounded-[22px] border border-[var(--border-color)] bg-[var(--bg-surface)] p-4">
      <div className="mb-3 flex items-center justify-between gap-3">
        <div>
          <div className="text-base font-semibold text-[var(--text-primary)]">{title}</div>
          <div className="mt-1 text-[11px] uppercase tracking-[0.16em] text-[var(--text-secondary)]">{style.hint}</div>
        </div>
        <div className={`rounded-full border px-2.5 py-1 text-[11px] font-semibold ${style.badge}`}>板块流动</div>
      </div>

      <div className="space-y-2">
        {safeItems.length ? (
          safeItems.slice(0, 3).map((item, index) => {
            const score = Number(item.score ?? item.strength ?? 0);
            const rawChange = item?.change;
            const hasChange = rawChange !== null && rawChange !== undefined && rawChange !== '';
            const change = hasChange ? Number(rawChange) : null;
            const width = `${(Math.abs(score) / max) * 100}%`;
            const positive = Number.isFinite(change) ? change >= 0 : false;
            return (
              <div key={`${item.name}-${index}`} className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-2">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="truncate text-sm font-semibold text-[var(--text-primary)]">{item.name || '数据暂缺'}</div>
                    <div className="mt-1 truncate text-xs text-[var(--text-secondary)]">龙头：{item.leader || '数据暂缺'}</div>
                  </div>
                  <div className="text-right">
                    <div className={`text-sm font-bold ${
                      Number.isFinite(change) ? (positive ? 'text-emerald-600' : 'text-rose-600') : 'text-[var(--text-secondary)]'
                    }`}>
                      {Number.isFinite(change) ? `${positive && change > 0 ? '+' : ''}${change.toFixed(2)}%` : '--'}
                    </div>
                    <div className="text-[11px] text-[var(--text-secondary)]">强度 {Number.isFinite(score) ? score.toFixed(0) : '0'}</div>
                  </div>
                </div>
                <div className="mt-2 h-2 rounded-full bg-[var(--bg-surface)]">
                  <div className={`h-2 rounded-full bg-gradient-to-r ${style.bar}`} style={{ width }} />
                </div>
                <div className="mt-2 text-xs leading-5 text-[var(--text-secondary)]">
                  {item.judgment || item.note || '板块轮动信号持续观察。'}
                </div>
              </div>
            );
          })
        ) : (
          <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-surface)] px-4 py-4 text-sm text-[var(--text-secondary)]">
            暂无板块流动数据
          </div>
        )}
      </div>
    </div>
  );
}

export default function FundFlowPanel({ data, themes, loading }) {
  const mainline = themes?.mainline || [];
  const watch = themes?.watch || [];
  const alive = themes?.alive || [];
  const inflowTop10 = data?.stock_inflow_top10;
  const outflowTop10 = data?.stock_outflow_top10;
  const stockIn = Array.isArray(inflowTop10) && inflowTop10.length ? inflowTop10 : data?.stock_inflow_top5 || [];
  const stockOut = Array.isArray(outflowTop10) && outflowTop10.length ? outflowTop10 : data?.stock_outflow_top5 || [];
  const hasThemeFlow = mainline.length > 0 || watch.length > 0 || alive.length > 0;

  return (
    <motion.section
      id="fund-panel"
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35, delay: 0.15 }}
      className="glass-card rounded-[28px] p-5"
    >
      <div className="mb-4 flex items-center justify-between">
        <div>
          <div className="text-sm font-semibold uppercase tracking-[0.24em] text-cyan-600/80">Fund Flow</div>
          <div className="mt-1 text-[18px] font-semibold text-[var(--text-primary)]">资金流向</div>
          <div className="mt-1 text-xs text-[var(--text-secondary)]">板块流动看主题轮动，个股流向看净流入 / 净流出。</div>
        </div>
        <div className="rounded-full border border-[var(--border-color)] bg-[var(--bg-surface)] px-3 py-1 text-xs font-semibold text-[var(--text-secondary)]">
          Board + Stock
        </div>
      </div>

      {loading ? (
        <div className="space-y-3">
          <div className="grid gap-3 xl:grid-cols-3">
            {[...Array(3)].map((_, index) => (
              <div key={index} className="h-56 animate-pulse rounded-[22px] bg-[var(--bg-surface)]" />
            ))}
          </div>
          <div className="grid gap-3 xl:grid-cols-2">
            {[...Array(2)].map((_, index) => (
              <div key={index} className="h-52 animate-pulse rounded-[22px] bg-[var(--bg-surface)]" />
            ))}
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          {hasThemeFlow ? (
            <div className="grid gap-3 xl:grid-cols-3">
              <ThemeFlowCard title="主线板块流动" items={mainline} tone="main" />
              <ThemeFlowCard title="观察板块流动" items={watch} tone="watch" />
              <ThemeFlowCard title="活口板块流动" items={alive} tone="alive" />
            </div>
          ) : (
            <div className="rounded-[22px] border border-amber-400/20 bg-amber-50 px-4 py-3 text-sm text-amber-700">
              当前未获取到主题板块轮动数据，下面先展示个股资金流。
            </div>
          )}
          <div className="grid gap-3 xl:grid-cols-2">
            <FlowTable title="个股净流入 TOP10" items={stockIn} direction="in" />
            <FlowTable title="个股净流出 TOP10" items={stockOut} direction="out" />
          </div>
        </div>
      )}
    </motion.section>
  );
}
