/**
 * 从股票代码提取纯代码（去掉.SH/.SZ后缀）
 */
export function extractStockCode(fullCode) {
  if (!fullCode) return '';
  return fullCode.replace(/\.(SH|SZ|BJ)$/i, '');
}

/**
 * 获取股票中文名称
 */
export function getStockName(fullCode) {
  const code = extractStockCode(fullCode);
  return STOCK_NAME_MAP[code] || fullCode;
}

/**
 * 获取股票所属行业
 */
export function getStockIndustry(fullCode) {
  const code = extractStockCode(fullCode);
  return STOCK_INDUSTRY_MAP[code] || '--';
}
